<style>
.ls-page{max-width:1100px;margin:auto;padding:24px 16px;color:#102a5a}.ls-page h1{font-size:30px;font-weight:800;margin:16px 0 8px}.ls-page h2{font-size:19px;margin:0 0 16px}.ls-muted{color:#63769a}.ls-card{background:#fff;border:1px solid #dbe4f0;border-radius:14px;padding:24px;margin:20px 0;box-shadow:0 7px 22px #1232670f}.ls-mode{color:#0d5ee8;font-size:22px}.ls-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}.ls-button{display:inline-block;background:#0d5ee8;color:white!important;border:1px solid #0d5ee8;border-radius:9px;padding:12px 18px;text-decoration:none;font:inherit;font-weight:700;cursor:pointer}.ls-button.secondary{background:white;color:#0d5ee8!important}.ls-notice{background:#eff6ff;border:1px solid #bdd7ff;border-radius:9px;padding:16px;margin:16px 0}.ls-errors{background:#fff1f2;color:#9f1239}.ls-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.ls-field label{display:block;font-weight:700;margin-bottom:8px}.ls-field input{box-sizing:border-box;width:100%;padding:12px;border:1px solid #dbe4f0;border-radius:8px;font:inherit}.ls-check{display:flex;align-items:flex-start;gap:10px;margin:20px 0}.ls-check input{margin-top:4px}.ls-page button:disabled{opacity:.55;cursor:wait}@media(max-width:640px){.ls-grid{grid-template-columns:1fr}.ls-card{padding:18px}.ls-actions>*{width:100%;text-align:center;box-sizing:border-box}}
</style>
